      "conversao_ads",
      "cpa_ads",
      "cpc_ads",
      "ctr_ads",
      "custo_produtos_vendidos",
      "desconto_vendedor",
      "esperado_meta",
      // D-412 (METRICS 5O): quem paga o frete.
      "frete_bancado_ml_comprador",
      "frete_bancado_ml_vendedor",
      // D-397 (METRICS 5L): o detector de frete.
      "frete_excedente_estimado",
      "frete_medio_pedido",
      "frete_pago_comprador",
      "frete_vendedor",
