      "investimento_ads",
      "lucro_estimado_apos_ads",
      "margem_apos_imposto",
      "margem_contribuicao",
      "margem_operacional_pedido",
      "margem_venda",
      "meta_diaria_necessaria",
      // D-436 (METRICS 5T): o consolidado entre marketplaces.
      "multicanal_compras",
      "multicanal_receita_bruta",
      // D-603: a taxa de cancelamento por compra.
      "multicanal_taxa_cancelamento",
      "multicanal_ticket_medio",
      "multicanal_unidades",
      "nivel_anomalia_frete",
      "nivel_sinal_ads",
      "pedidos",
      "pedidos_cancelados",
      "pedidos_por_pack",
      "preco_medio_praticado",
      "projecao_fechamento_mes",
      "projecao_sazonal_mes",
      "receita_ads",
      "receita_bruta",
      "receita_media_diaria",
      "resultado_apos_imposto",
      "resultado_contribuicao",
      "resultado_venda",
      "roas",
      // D-451: o repasse da Shopee (a liberar, diferenca, liberado).
      "shopee_a_liberar",
      // D-449: Ads CPC da loja Shopee (ACOS, investimento, vendas com Ads, ROAS, TACoS).
      "shopee_acos",
      // D-485: os ajustes da Shopee depois do repasse.
      "shopee_ajustes_pos_repasse",
      // D-443: a composicao do recebido da Shopee.
      "shopee_composicao_recebido",
      // D-437 (METRICS 5U): o faturamento da Shopee, entre as de vendas (5S).
      "shopee_custo_produtos",
      "shopee_imposto_estimado",
      "shopee_investimento_ads",
      "shopee_margem_contribuicao",
      "shopee_margem_venda",
      "shopee_pedidos",
      "shopee_recebido",
      "shopee_receita_ads",
      "shopee_receita_bruta",
      // D-439: o grao de SKU da receita da Shopee.
      "shopee_receita_item",
      "shopee_repasse_diferenca",
      "shopee_repasse_liberado",
      "shopee_resultado_apos_imposto",
      "shopee_resultado_contribuicao",
      "shopee_resultado_venda",
