/**
 * D-417: a conta que para de sincronizar avisa. `domain_events` e `sync_runs`
 * são append-only (e o evento prende a conta com `on delete restrict`): cada
 * teste roda numa transação desfeita no fim -- a lição de D-411.
 */
describe("sync.delayed / sync.failed: a conta que para de sincronizar avisa (D-417)", () => {
  const CONTA = "eeee4151-0000-4000-8000-00000000e415";

  async function naTransacao(corpo: () => Promise<void>): Promise<void> {
    await client.query("begin");

    try {
      await client.query(
        `insert into public.ml_accounts (id, organization_id, label, slug, status, seller_id, connected_at)
         values ($1,$2,'Conta parada','rlstest-sync-parada','CONNECTED',9990415, now() - interval '30 days')`,
        [CONTA, ORG_SB],
      );
      await corpo();
    } finally {
      await client.query("rollback");
    }
  }

  /** Uma execução da reconciliação de pedidos que terminou há `horas` horas. */
  async function execucao(status: "done" | "failed", horas: number, motivo: string | null = null): Promise<void> {
    await client.query(
      `insert into public.sync_runs
         (organization_id, ml_account_id, job_id, resource, channel, status, reason, items_processed, started_at, finished_at)
       values ($1,$2,gen_random_uuid(),'orders','reconciliation',$3,$4,0,
               now() - make_interval(hours => $5) - interval '1 minute', now() - make_interval(hours => $5))`,
      [ORG_SB, CONTA, status, motivo, horas],
    );
  }

  async function avisos(): Promise<{ id: string; event_type: string; severity: string; after: Record<string, unknown> }[]> {
    const { rows } = await client.query<{ id: string; event_type: string; severity: string; after: Record<string, unknown> }>(
      `select id::text, event_type, severity, after from public.domain_events
       where ml_account_id = $1 and event_type like 'sync.%' order by occurred_at, event_type`,
      [CONTA],
    );

    return rows;
  }

  it("reconciliação falhando e último sucesso há mais de 3 h: um aviso importante por episódio", async () => {
    await naTransacao(async () => {
      await execucao("done", 5);
      await execucao("failed", 0, "Mercado Livre respondeu 403 para GET /orders/search.");
      await execucao("failed", 0, "Mercado Livre respondeu 403 para GET /orders/search.");

      const lista = await avisos();

      expect(lista).toHaveLength(1);
      expect(lista[0]).toMatchObject({
        event_type: "sync.delayed",
        severity: "importante",
        after: { tipo: "reconciliacao", label: "Conta parada", horas: 5, motivo: "Mercado Livre respondeu 403 para GET /orders/search." },
      });

      // O fan-out entrega a quem alcança a conta: o admin, não o analista sem permissão nela.
      const { rows } = await client.query<{ user_id: string }>(
        `select nr.user_id from public.notification_recipients nr
         join public.notifications n on n.id = nr.notification_id where n.domain_event_id = $1`,
        [lista[0]?.id],
      );
      const destinatarios = rows.map((r) => r.user_id);

      expect(destinatarios).toContain(ADMIN_SB);
      expect(destinatarios).not.toContain(ANALISTA_SB);
    });
  });

  it("passando de 12 h vira crítico; sucesso recente não avisa, e o sucesso seguinte começa outro episódio", async () => {
    await naTransacao(async () => {
      await execucao("done", 13);
      await execucao("failed", 0, null);

      expect((await avisos()).map((a) => [a.event_type, a.severity, a.after.horas])).toEqual([["sync.failed", "critico", 13]]);

      await execucao("done", 0);
      await execucao("failed", 0, null);

      expect(await avisos()).toHaveLength(1);
    });
  });

  it("a conta que entra em ERROR avisa na hora, crítico, uma vez; continuar em ERROR não repete", async () => {
    await naTransacao(async () => {
      await client.query(
        "update public.ml_accounts set status = 'ERROR', last_error = 'Mercado Livre recusou a troca de token: invalid_grant.' where id = $1",
        [CONTA],
      );
      await client.query("update public.ml_accounts set last_error = 'outra falha' where id = $1", [CONTA]);
      await client.query("update public.ml_accounts set status = 'ERROR' where id = $1", [CONTA]);

      const lista = await avisos();

      expect(lista).toHaveLength(1);
      expect(lista[0]).toMatchObject({
        event_type: "sync.failed",
        severity: "critico",
        after: { tipo: "conta_em_erro", label: "Conta parada", motivo: "Mercado Livre recusou a troca de token: invalid_grant." },
      });
    });
  });
});

/**
 * D-418: o banco vigia a sincronização -- o caso que o gatilho de D-417 não vê,
 * a reconciliação que para de RODAR. Transação desfeita, como em D-417.
 */
describe("vigiar_sincronizacao: a reconciliação que para de rodar também avisa (D-418)", () => {
  const CONTA = "eeee4181-0000-4000-8000-00000000e418";

  async function naTransacao(corpo: () => Promise<void>): Promise<void> {
    await client.query("begin");

    try {
      await client.query(
        `insert into public.ml_accounts (id, organization_id, label, slug, status, seller_id, connected_at)
         values ($1,$2,'Conta muda','rlstest-sync-vigia','CONNECTED',9990418, now() - interval '30 days')`,
        [CONTA, ORG_SB],
      );
      await corpo();
    } finally {
      await client.query("rollback");
    }
  }

  async function execucao(status: "done" | "failed", horas: number, motivo: string | null = null): Promise<void> {
    await client.query(
      `insert into public.sync_runs
         (organization_id, ml_account_id, job_id, resource, channel, status, reason, items_processed, started_at, finished_at)
       values ($1,$2,gen_random_uuid(),'orders','reconciliation',$3,$4,0,
               now() - make_interval(hours => $5) - interval '1 minute', now() - make_interval(hours => $5))`,
      [ORG_SB, CONTA, status, motivo, horas],
    );
  }

  async function vigiar(): Promise<void> {
    await client.query("select private.vigiar_sincronizacao()");
  }

  async function avisos(): Promise<{ event_type: string; after: Record<string, unknown> }[]> {
    const { rows } = await client.query<{ event_type: string; after: Record<string, unknown> }>(
      `select event_type, after from public.domain_events
       where ml_account_id = $1 and event_type like 'sync.%' order by occurred_at, event_type`,
      [CONTA],
    );

    return rows;
  }

  it("sem nenhuma execução há 5 h: avisa sync.delayed, dizendo que não rodou; vigiar de novo não repete", async () => {
    await naTransacao(async () => {
      await execucao("done", 5);
      await vigiar();
      await vigiar();

      const lista = await avisos();

      expect(lista).toHaveLength(1);
      expect(lista[0]).toMatchObject({
        event_type: "sync.delayed",
        after: {
          tipo: "reconciliacao",
          label: "Conta muda",
          horas: 5,
          motivo: "Nenhuma reconciliação de pedidos rodou desde o último sucesso.",
        },
      });
    });
  });

  it("o vigia e o gatilho de D-417 usam a mesma chave: o mesmo episódio avisa uma vez só", async () => {
    await naTransacao(async () => {
      await execucao("done", 14);
      await vigiar();
      await execucao("failed", 0, "Mercado Livre respondeu 403 para GET /orders/search.");

      expect((await avisos()).map((a) => a.event_type)).toEqual(["sync.failed"]);
    });
  });

  it("sucesso recente não avisa; a falha que ainda não tinha avisado dá o motivo ao vigia", async () => {
    await naTransacao(async () => {
      await execucao("done", 1);
      await vigiar();

      expect(await avisos()).toHaveLength(0);
    });

    await naTransacao(async () => {
      // A falha de 4 h atrás veio 1 h depois do sucesso: o gatilho não avisou.
      await execucao("done", 5);
      await execucao("failed", 4, "Mercado Livre respondeu 429.");
      await vigiar();

      expect(await avisos()).toMatchObject([
        { event_type: "sync.delayed", after: { horas: 5, motivo: "Mercado Livre respondeu 429." } },
      ]);
    });
  });

  it("conta em ERROR fica de fora do vigia -- o gatilho da conta já avisou", async () => {
    await naTransacao(async () => {
      await execucao("done", 20);
      await client.query("update public.ml_accounts set status = 'ERROR', last_error = 'x' where id = $1", [CONTA]);
      await vigiar();

      const tipos = (await avisos()).map((a) => a.after.tipo);

      expect(tipos).toEqual(["conta_em_erro"]);
    });
  });

  it("o ato de produção agenda o vigia a cada 30 minutos, pelo nome", async () => {
    await client.query("begin");

    try {
      await client.query("select private.agendar_vigia_da_sincronizacao()");
      const { rows } = await client.query<{ schedule: string; command: string }>(
        "select schedule, command from cron.job where jobname = 'vigiar-sincronizacao'",
      );

      expect(rows).toEqual([{ schedule: "*/30 * * * *", command: "select private.vigiar_sincronizacao()" }]);
    } finally {
      await client.query("rollback");
    }
  });
});

/*
  D-489: os campos do order_income que as leituras usam viram colunas geradas
  de shopee_orders. O Postgres as calcula na gravacao; a view de vendas e o
  pedido do faturamento leem as colunas, sem descompactar o json.
*/
describe("campos do financeiro Shopee como colunas geradas (D-489)", () => {
  const ORG = "66666666-0000-4000-8000-00000000d489";
  const LOJA = "dddd4890-0000-4000-8000-0000000a0489";
  const DIA = "2026-08-20";

  async function pedido(sn: string, renda: Record<string, unknown> | null) {
    await client.query(
      `insert into public.shopee_orders
         (shopee_shop_id, organization_id, order_sn, order_status, shopee_created_at, shopee_updated_at, paid_at,
          escrow_amount, order_income, financials_synced_at)
       values ($1, $2, $3, 'COMPLETED', $4, $4, $4, 80, $5::jsonb, case when $5::jsonb is null then null else now() end)`,
      [LOJA, ORG, sn, `${DIA}T15:00:00Z`, renda === null ? null : JSON.stringify(renda)],
    );
    await client.query(
      `insert into public.shopee_order_items (shopee_shop_id, order_sn, position, organization_id, item_id, quantity, discounted_price)
       values ($1, $2, 0, $3, 1, 2, 30)`,
      [LOJA, sn, ORG],
    );
  }

  const colunas = async (sn: string) =>
    (
      await client.query<Record<string, string | null>>(
        `select order_discounted_price::text, shipping_fee_discount_from_3pl::text, final_return_to_seller_shipping_fee::text,
                seller_coin_cash_back::text, coins::text, shipping_seller_protection_fee_amount::text
           from public.shopee_orders where shopee_shop_id = $1 and order_sn = $2`,
        [LOJA, sn],
      )
    ).rows[0];

  beforeAll(async () => {
    await client.query("insert into public.organizations (id, name, slug) values ($1, 'Org D-489', 'org-d489') on conflict (id) do nothing", [ORG]);
    await client.query(
      `insert into public.shopee_shops (id, organization_id, environment, shop_id, shop_name, status, connected_at, orders_synced_until, orders_last_success_at)
       values ($1, $2, 'live', 990489001, 'Loja D-489', 'CONNECTED', now(), now(), now()) on conflict do nothing`,
      [LOJA, ORG],
    );
    // N1: os seis como numero. N2: texto, objeto e nulo -- nenhum vira numero.
    await pedido("N1", {
      order_discounted_price: 100,
      shipping_fee_discount_from_3pl: 1.5,
      final_return_to_seller_shipping_fee: 4,
      seller_coin_cash_back: 0.25,
      coins: 2,
      shipping_seller_protection_fee_amount: 0.49,
      escrow_amount: 80,
    });
    await pedido("N2", {
      order_discounted_price: "100",
      shipping_fee_discount_from_3pl: { valor: 1 },
      final_return_to_seller_shipping_fee: null,
      coins: [1],
      escrow_amount: 80,
    });
    await pedido("N3", null);
  });

  afterAll(async () => {
    await client.query("delete from public.shopee_shops where id = $1", [LOJA]);
  });

  it("as colunas vem do order_income na gravacao, e so numero vira numero", async () => {
    expect(await colunas("N1")).toEqual({
      order_discounted_price: "100",
      shipping_fee_discount_from_3pl: "1.5",
      final_return_to_seller_shipping_fee: "4",
      seller_coin_cash_back: "0.25",
      coins: "2",
      shipping_seller_protection_fee_amount: "0.49",
    });
    // Texto, objeto, lista, nulo e chave ausente: NULO, e a gravacao do financeiro nao trava.
    expect(Object.values((await colunas("N2")) ?? {})).toEqual([null, null, null, null, null, null]);
    expect(Object.values((await colunas("N3")) ?? {})).toEqual([null, null, null, null, null, null]);
  });

  it("acompanham a releitura do financeiro, e nao se gravam a mao", async () => {
    await client.query(
      `update public.shopee_orders set order_income = order_income || '{"coins": 3, "order_discounted_price": 90}'::jsonb
        where shopee_shop_id = $1 and order_sn = 'N1'`,
      [LOJA],
    );
    expect(await colunas("N1")).toMatchObject({ coins: "3", order_discounted_price: "90" });
    await expect(client.query("update public.shopee_orders set coins = 1 where shopee_shop_id = $1", [LOJA])).rejects.toThrow(/can only be updated to DEFAULT/i);
    await client.query(
      `update public.shopee_orders set order_income = order_income || '{"coins": 2, "order_discounted_price": 100}'::jsonb
        where shopee_shop_id = $1 and order_sn = 'N1'`,
      [LOJA],
    );
  });

  it("a view de vendas e o pedido do faturamento leem as colunas", async () => {
    const vendas = await client.query<{ order_sn: string; receita_bruta: string | null }>(
      "select order_sn, receita_bruta::text from public.shopee_sales_orders where shopee_shop_id = $1 order by order_sn",
      [LOJA],
    );

    // N2 traz o preco como texto: a receita vem dos itens (2 x 30), como quando o campo falta.
    expect(vendas.rows).toEqual([
      { order_sn: "N1", receita_bruta: "100" },
      { order_sn: "N2", receita_bruta: "60" },
      { order_sn: "N3", receita_bruta: "60" },
    ]);

    const pedidos = await client.query<Record<string, string | null>>(
      `select order_sn, frete_devolucao::text, cupom_loja::text, moedas_shopee::text, protecao_envio::text
         from public.get_shopee_faturamento_pedidos($1, $2, $2, null) order by order_sn`,
      [ORG, DIA],
    );

    expect(pedidos.rows).toEqual([
      { order_sn: "N1", frete_devolucao: "4", cupom_loja: "0.25", moedas_shopee: "2", protecao_envio: "0.49" },
      { order_sn: "N2", frete_devolucao: null, cupom_loja: null, moedas_shopee: null, protecao_envio: null },
      { order_sn: "N3", frete_devolucao: null, cupom_loja: null, moedas_shopee: null, protecao_envio: null },
    ]);
  });
});

/*
  D-493 (C-67): as vendas por anuncio da Shopee em get_shopee_listings. A
  venda casa com a linha do anuncio por (loja, item, variacao), com a regra
  do item do C-59 (shopee_sales_items): pedido VALIDA e receita = preco com o
  desconto da loja x quantidade; preco 0 = desconhecida.
*/
describe("vendas por anúncio da Shopee (D-493, C-67)", () => {
  const ORG = "66666666-0000-4000-8000-00000000d493";
  const ADMIN = "aaaaaaaa-0000-4000-8000-00000000d493";
  const LOJA = "dddd4930-0000-4000-8000-0000000a0493";
  const NUNCA = "dddd4930-0000-4000-8000-0000000b0493";
  const DE = "2026-08-10";
  const ATE = "2026-08-11";

  async function item(loja: string, id: number, nome: string, temVariacao: boolean) {
    await client.query(
      `insert into public.shopee_items (shopee_shop_id, organization_id, item_id, item_status, shopee_updated_at, item_name, has_model, details_synced_at, details_update_time)
       values ($1, $2, $3, 'NORMAL', now() - interval '2 days', $4, $5, now(), now() - interval '2 days')`,
      [loja, ORG, id, nome, temVariacao],
    );
  }

  async function pedido(sn: string, status: string, dia: string, pago: boolean, itens: [number, number | null, number, number][]) {
    const quando = `${dia}T15:00:00Z`;
    await client.query(
      `insert into public.shopee_orders (shopee_shop_id, organization_id, order_sn, order_status, shopee_created_at, shopee_updated_at, paid_at)
       values ($1, $2, $3, $4, $5, $5, case when $6 then $5::timestamptz end)`,
      [LOJA, ORG, sn, status, quando, pago],
    );
    let posicao = 0;
    for (const [itemId, modelId, qtd, preco] of itens) {
      await client.query(
        `insert into public.shopee_order_items (shopee_shop_id, order_sn, position, organization_id, item_id, model_id, quantity, discounted_price)
         values ($1, $2, $3, $4, $5, $6, $7, $8)`,
        [LOJA, sn, posicao, ORG, itemId, modelId, qtd, preco],
      );
      posicao += 1;
    }
  }

  type Linha = Record<string, string | null>;

  const anuncios = (args: string, usuario = ADMIN) =>
    asUser<Linha>(
      usuario,
      `select item_id, model_id, unidades_vendidas, receita_bruta, pedidos, unidades_sem_receita,
              recorte_unidades, recorte_receita, recorte_unidades_sem_receita, total_count
         from public.get_shopee_listings('${ORG}', ${args})`,
    );

  beforeAll(async () => {
    await client.query(
      `insert into auth.users (id, instance_id, aud, role, email, encrypted_password, email_confirmed_at, raw_user_meta_data, created_at, updated_at)
       values ($1, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'admin-d493@rls.test', 'x', now(), '{}', now(), now())
       on conflict (id) do nothing`,
      [ADMIN],
    );
    await client.query("insert into public.organizations (id, name, slug) values ($1, 'Org D-493', 'org-d493') on conflict (id) do nothing", [ORG]);
    await client.query("insert into public.organization_members (organization_id, user_id, role) values ($1, $2, 'ADMIN') on conflict do nothing", [ORG, ADMIN]);
    await client.query(
      `insert into public.shopee_shops (id, organization_id, environment, shop_id, shop_name, status, connected_at, orders_synced_until, orders_last_success_at)
       values ($1, $3, 'live', 990493001, 'Loja Lida', 'CONNECTED', now(), now(), now()),
              ($2, $3, 'live', 990493002, 'Nunca Lida', 'CONNECTED', now(), null, null)`,
      [LOJA, NUNCA, ORG],
    );
    await item(LOJA, 5001, "Painel", false);
    await item(LOJA, 5002, "Bau", true);
    await client.query(
      `insert into public.shopee_item_models (shopee_shop_id, item_id, model_id, organization_id, model_name)
       values ($1, 5002, 1, $2, 'Azul'), ($1, 5002, 2, $2, 'Preto')`,
      [LOJA, ORG],
    );
    await item(LOJA, 5003, "Capa", false);
    await item(NUNCA, 5004, "Kit", false);

    // [item, variacao, quantidade, preco]
    await pedido("O1", "COMPLETED", DE, true, [[5001, null, 2, 50], [5002, 1, 1, 30]]);
    await pedido("O2", "SHIPPED", ATE, true, [[5001, null, 1, 50]]);
    await pedido("O3", "CANCELLED", DE, true, [[5001, null, 5, 50]]);
    // Bundle: o Preto saiu com preco 0 -- receita desconhecida.
    await pedido("O4", "COMPLETED", ATE, true, [[5002, 2, 1, 0], [5002, 1, 1, 30]]);
    await pedido("O5", "COMPLETED", "2026-08-15", true, [[5003, null, 1, 10]]);
    await pedido("O6", "UNPAID", DE, false, [[5003, null, 1, 10]]);
  });

  afterAll(async () => {
    await client.query("delete from public.shopee_shops where id = any($1::uuid[])", [[LOJA, NUNCA]]);
  });

  const periodo = `'${LOJA}', null, null, 200, 0, '${DE}', '${ATE}'`;

  it("as vendas validas do periodo por anuncio e variacao; a de preco 0 conta a parte", async () => {
    const linhas = await anuncios(`${periodo}, null, null`);

    // O3 cancelado, O5 fora do periodo e O6 nao pago ficam fora. O recorte e o filtro inteiro.
    expect(linhas.map((l) => [l.item_id, l.model_id, l.unidades_vendidas, l.receita_bruta, l.pedidos, l.unidades_sem_receita])).toEqual([
      ["5002", "1", "2", "60.00", "2", "0"],
      ["5002", "2", "1", null, "1", "1"],
      ["5003", null, "0", "0.00", "0", "0"],
      ["5001", null, "3", "150.00", "2", "0"],
    ]);
    expect(linhas[0]).toMatchObject({ recorte_unidades: "6", recorte_receita: "210.00", recorte_unidades_sem_receita: "1", total_count: "4" });
  });

  it("ordem por vendas ou por receita, com desempate pela chave; o filtro vendeu e o recorte acompanham", async () => {
    const vendas = await anuncios(`${periodo}, null, 'vendas'`);
    const receita = await anuncios(`${periodo}, null, 'receita'`);
    const com = await anuncios(`${periodo}, 'com', null`);
    const sem = await anuncios(`${periodo}, 'sem', null`);
    const pagina = await anuncios(`'${LOJA}', null, null, 1, 1, '${DE}', '${ATE}', null, 'vendas'`);

    expect(vendas.map((l) => [l.item_id, l.model_id])).toEqual([["5001", null], ["5002", "1"], ["5002", "2"], ["5003", null]]);
    // Receita desconhecida vai para o fim, nunca como zero.
    expect(receita.map((l) => [l.item_id, l.model_id])).toEqual([["5001", null], ["5002", "1"], ["5003", null], ["5002", "2"]]);
    expect(com.map((l) => l.item_id)).toEqual(["5002", "5002", "5001"]);
    expect(com[0]).toMatchObject({ total_count: "3", recorte_unidades: "6", recorte_receita: "210.00" });
    expect(sem).toEqual([expect.objectContaining({ item_id: "5003", total_count: "1", recorte_unidades: "0", recorte_receita: "0.00" })]);
    // O recorte e de antes do limite: a pagina 2 de 1 linha ainda soma tudo.
    expect(pagina).toEqual([expect.objectContaining({ item_id: "5002", model_id: "1", total_count: "4", recorte_unidades: "6" })]);
  });

  it("sem periodo, as colunas novas vem NULAS e a lista de sempre; loja nunca lida, NULO", async () => {
    const semPeriodo = await anuncios(`'${LOJA}', null, null, 200, 0`);
    const nunca = await anuncios(`'${NUNCA}', null, null, 200, 0, '${DE}', '${ATE}'`);

    expect(semPeriodo.map((l) => l.item_id)).toEqual(["5002", "5002", "5003", "5001"]);
    expect(semPeriodo.every((l) => l.unidades_vendidas === null && l.receita_bruta === null && l.recorte_unidades === null)).toBe(true);
    expect(nunca).toEqual([expect.objectContaining({ item_id: "5004", unidades_vendidas: null, receita_bruta: null, recorte_unidades: null })]);
  });

  it("recusa vendeu ou ordem sem periodo, periodo pela metade e valor fora da lista", async () => {
    await expect(anuncios(`'${LOJA}', null, null, 50, 0, null, null, 'com', null`)).rejects.toThrow(/pedem o periodo/);
    await expect(anuncios(`'${LOJA}', null, null, 50, 0, null, null, null, 'vendas'`)).rejects.toThrow(/pedem o periodo/);
    await expect(anuncios(`'${LOJA}', null, null, 50, 0, '${DE}', null, null, null`)).rejects.toThrow(/periodo invalido/);
    await expect(anuncios(`${periodo}, 'talvez', null`)).rejects.toThrow(/vendeu invalido/);
    await expect(anuncios(`${periodo}, null, 'lucro'`)).rejects.toThrow(/ordem invalida/);
  });
});

/**
 * ml_sales_lines (D-499): as linhas de venda do Mercado Livre que o
 * faturamento soma, numa tabela estreita mantida por gatilhos. Cada mudança
 * que muda a soma (status, data, pacote, item, SKU, preço, comissão, frete
 * rateado, desconto) recalcula as linhas do pedido; a regravação sem mudança,
 * que o webhook faz o tempo todo, não toca a tabela.
 */
describe("ml_sales_lines: as linhas de venda do faturamento do ML, mantidas por gatilhos (D-499)", () => {
  const CONTA_PERMITIDA = "aaaa4999-0000-4000-8000-00000000a499"; // ANALISTA_SB tem permissão aqui.
  const CONTA_SEM = "bbbb4999-0000-4000-8000-00000000b499"; // mesma organização, sem permissão.
  const PEDIDO = 9904990001;
  const OUTRO = 9904990002;
  const ENVIO = 9904990900;
  let skuId = "";

  beforeAll(async () => {
    await client.query(
      `insert into public.ml_accounts (id, organization_id, label, slug, status)
       values ($1,$3,'Linhas A','rlstest-linhas-a','PENDING'), ($2,$3,'Linhas B','rlstest-linhas-b','PENDING')
       on conflict do nothing`,
      [CONTA_PERMITIDA, CONTA_SEM, ORG_SB],
    );
    await client.query(
      "insert into public.user_account_permissions (user_id, ml_account_id) values ($1,$2) on conflict do nothing",
      [ANALISTA_SB, CONTA_PERMITIDA],
    );

    const sku = await client.query<{ id: string }>(
      `insert into public.skus (organization_id, sku, kind, purchase_cost)
       values ($1, 'RLSTEST-LINHAS-D499', 'PRODUTO', 20)
       on conflict on constraint skus_org_key_unique do update set sku = excluded.sku
       returning id`,
      [ORG_SB],
    );

    skuId = sku.rows[0]?.id ?? "";

    await client.query(
      `insert into public.orders
         (id, organization_id, ml_account_id, pack_id, status, date_created, date_last_updated, total_amount, currency_id, shipping_id)
       values ($1, $3, $4, null, 'paid', timestamptz '2026-10-10 15:00+00', timestamptz '2026-10-10 15:00+00', 80, 'BRL', null),
              ($2, $3, $5, null, 'paid', timestamptz '2026-10-10 16:00+00', timestamptz '2026-10-10 16:00+00', 80, 'BRL', null)
       on conflict (id) do nothing`,
      [PEDIDO, OUTRO, ORG_SB, CONTA_PERMITIDA, CONTA_SEM],
    );
  });

  afterAll(async () => {
    await client.query("delete from public.order_financials where order_id = any($1)", [[PEDIDO, OUTRO]]);
    await client.query("delete from public.order_items where order_id = any($1)", [[PEDIDO, OUTRO]]);
    await client.query("delete from public.orders where id = any($1)", [[PEDIDO, OUTRO]]);
    await client.query("delete from public.ml_accounts where id = any($1)", [[CONTA_PERMITIDA, CONTA_SEM]]);
  });

  async function linhas(pedido = PEDIDO): Promise<Record<string, string | null>[]> {
    const { rows } = await client.query<Record<string, string | null>>(
      `select l.line_id::text, l.sku_id::text, l.quantity::text, l.unit_price::text, l.sale_fee::text,
              l.shipping_share::text, l.seller_discount::text, l.pack_id::text, l.date_created::text, l.xmin::text as versao
       from public.ml_sales_lines l
       join public.order_items i on i.id = l.line_id
       where l.order_id = $1
       order by i.position`,
      [pedido],
    );

    return rows;
  }

  it("o item do pedido pago cria a linha; o financeiro preenche o frete e o desconto", async () => {
    expect(await linhas()).toEqual([]);

    await client.query(
      `insert into public.order_items
         (order_id, organization_id, ml_account_id, position, item_id, variation_id, title, quantity, unit_price, currency_id, sku_id, sale_fee)
       values ($1, $3, $4, 0, 'MLB9499001', null, 'Linha A', 1, 80, 'BRL', null, 9.6),
              ($2, $3, $5, 0, 'MLB9499002', null, 'Linha B', 1, 80, 'BRL', null, 9.6)`,
      [PEDIDO, OUTRO, ORG_SB, CONTA_PERMITIDA, CONTA_SEM],
    );

    expect(await linhas()).toEqual([
      expect.objectContaining({ sku_id: null, quantity: "1", unit_price: "80", sale_fee: "9.6", shipping_share: null, seller_discount: null }),
    ]);

    await client.query(
      `insert into public.order_financials (order_id, organization_id, ml_account_id, seller_shipping_cost, seller_discount)
       values ($1, $2, $3, 12.5, 4), ($4, $2, $5, 14, 0)`,
      [PEDIDO, ORG_SB, CONTA_PERMITIDA, OUTRO, CONTA_SEM],
    );

    expect(await linhas()).toEqual([expect.objectContaining({ shipping_share: "12.5", seller_discount: "4" })]);
  });

  it("cancelar tira e voltar a pago devolve; parcialmente reembolsado continua", async () => {
    await client.query("update public.orders set status = 'cancelled' where id = $1", [PEDIDO]);
    expect(await linhas()).toEqual([]);

    await client.query("update public.orders set status = 'paid' where id = $1", [PEDIDO]);
    expect(await linhas()).toHaveLength(1);

    await client.query("update public.orders set status = 'partially_refunded' where id = $1", [PEDIDO]);
    expect(await linhas()).toHaveLength(1);
  });

  it("a segunda linha entra e sai; quantidade, SKU, preço, comissão, pacote, data e desconto acompanham", async () => {
    await client.query(
      `insert into public.order_items
         (order_id, organization_id, ml_account_id, position, item_id, variation_id, title, quantity, unit_price, currency_id, sale_fee)
       values ($1, $2, $3, 1, 'MLB9499003', null, 'Segunda linha', 1, 30, 'BRL', 3)`,
      [PEDIDO, ORG_SB, CONTA_PERMITIDA],
    );
    expect((await linhas()).map((l) => l.unit_price)).toEqual(["80", "30"]);
    // As duas linhas levam o frete e o desconto do pedido.
    expect((await linhas()).map((l) => l.shipping_share)).toEqual(["12.5", "12.5"]);

    await client.query("delete from public.order_items where order_id = $1 and position = 1", [PEDIDO]);
    expect((await linhas()).map((l) => l.unit_price)).toEqual(["80"]);

    // Uma coluna por vez, conferida logo depois: a próxima mudança recalcula o
    // pedido inteiro e esconderia um termo faltando no `when` do gatilho.
    const mudancas: [string, Record<string, string>][] = [
      ["update public.order_items set quantity = 2 where order_id = $1", { quantity: "2" }],
      [`update public.order_items set sku_id = '${skuId}' where order_id = $1`, { sku_id: skuId }],
      ["update public.order_items set unit_price = 85 where order_id = $1", { unit_price: "85" }],
      ["update public.order_items set sale_fee = 10 where order_id = $1", { sale_fee: "10" }],
      ["update public.orders set pack_id = 2000099049901 where id = $1", { pack_id: "2000099049901" }],
      ["update public.orders set date_created = timestamptz '2026-10-11 15:00+00' where id = $1", { date_created: "2026-10-11 15:00:00+00" }],
      ["update public.order_financials set seller_discount = 5 where order_id = $1", { seller_discount: "5" }],
    ];

    for (const [sql, esperado] of mudancas) {
      await client.query(sql, [PEDIDO]);
      expect(await linhas(), sql).toEqual([expect.objectContaining(esperado)]);
    }
  });

  it("item de outra conta não entra, como no faturamento", async () => {
    await client.query(
      `insert into public.order_items
         (order_id, organization_id, ml_account_id, position, item_id, variation_id, title, quantity, unit_price, currency_id, sale_fee)
       values ($1, $2, $3, 1, 'MLB9499004', null, 'Conta errada', 1, 30, 'BRL', 3)`,
      [PEDIDO, ORG_SB, CONTA_SEM],
    );

    expect(await linhas()).toHaveLength(1);

    await client.query("delete from public.order_items where order_id = $1 and position = 1", [PEDIDO]);
  });

  it("o rateio do envio compartilhado chega às linhas com a parte final", async () => {
    await client.query("update public.orders set shipping_id = $2, ml_account_id = $3 where id = any($1)", [
      [PEDIDO, OUTRO],
      ENVIO,
      CONTA_PERMITIDA,
    ]);
    await client.query("update public.order_items set ml_account_id = $2 where order_id = $1", [OUTRO, CONTA_PERMITIDA]);
    await client.query("update public.order_financials set ml_account_id = $2 where order_id = $1", [OUTRO, CONTA_PERMITIDA]);
    // Os dois com o MESMO custo: o envio é dividido pelo valor de cada pedido.
    await client.query("update public.orders set total_amount = 60 where id = $1", [OUTRO]);
    await client.query("update public.order_financials set seller_shipping_cost = 14 where order_id = any($1)", [[PEDIDO, OUTRO]]);

    const { rows } = await client.query<{ order_id: string; parte: string; linha: string }>(
      `select f.order_id::text, f.seller_shipping_share::text as parte, l.shipping_share::text as linha
       from public.order_financials f
       join public.ml_sales_lines l on l.order_id = f.order_id
       where f.order_id = any($1)
       order by f.order_id`,
      [[PEDIDO, OUTRO]],
    );

    expect(rows).toEqual([
      { order_id: String(PEDIDO), parte: "8.000000", linha: "8.000000" },
      { order_id: String(OUTRO), parte: "6.000000", linha: "6.000000" },
    ]);
  });

  it("a regravação sem mudança, como a do webhook, não toca a linha", async () => {
    const antes = await linhas();

    await client.query("update public.orders set status = status, pack_id = pack_id, date_last_updated = now() where id = $1", [PEDIDO]);
    await client.query("update public.order_items set quantity = quantity, unit_price = unit_price, title = 'Regravado' where order_id = $1", [
      PEDIDO,
    ]);
    await client.query("update public.order_financials set seller_discount = seller_discount where order_id = $1", [PEDIDO]);

    expect((await linhas()).map((l) => l.versao)).toEqual(antes.map((l) => l.versao));
  });

  it("a tabela inteira é exatamente a regra do faturamento aplicada às três tabelas", async () => {
    const { rows } = await client.query<{ diferencas: string }>(
      `with regra as (
         select i.id as line_id, o.id as order_id, o.organization_id, o.ml_account_id, o.date_created, o.pack_id, i.sku_id,
                i.quantity, i.unit_price, i.sale_fee, f.seller_shipping_share as shipping_share, f.seller_discount
         from public.orders o
         join public.order_items i
           on i.order_id = o.id and i.organization_id = o.organization_id and i.ml_account_id = o.ml_account_id
         left join public.order_financials f on f.order_id = o.id
         where o.status in ('paid', 'partially_refunded')
       ),
       tabela as (
         select line_id, order_id, organization_id, ml_account_id, date_created, pack_id, sku_id,
                quantity, unit_price, sale_fee, shipping_share, seller_discount
         from public.ml_sales_lines
       )
       select count(*)::text as diferencas
       from ((select * from regra except select * from tabela) union all (select * from tabela except select * from regra)) d`,
    );

    expect(rows[0]?.diferencas).toBe("0");
  });

  it("quem alcança a conta lê; ninguém grava direto, nem o worker", async () => {
    await client.query("update public.orders set ml_account_id = $2 where id = $1", [OUTRO, CONTA_SEM]);
    await client.query("update public.order_items set ml_account_id = $2 where order_id = $1", [OUTRO, CONTA_SEM]);

    const consulta = `select order_id::text from public.ml_sales_lines where order_id in (${String(PEDIDO)}, ${String(OUTRO)}) order by order_id`;
    const analista = await asUser<{ order_id: string }>(ANALISTA_SB, consulta);
    const admin = await asUser<{ order_id: string }>(ADMIN_SB, consulta);
    const outra = await asUser(DE_OUTRA_ORG, consulta);

    expect(analista.map((r) => r.order_id)).toEqual([String(PEDIDO)]);
    expect(admin.map((r) => r.order_id)).toEqual([String(PEDIDO), String(OUTRO)]);
    expect(outra).toEqual([]);
    await expect(asUser(ADMIN_SB, `delete from public.ml_sales_lines where order_id = ${String(PEDIDO)}`)).rejects.toThrow(
      /permission denied/i,
    );

    await client.query("begin");

    try {
      await client.query("set local role service_role");
      await expect(
        client.query(`update public.ml_sales_lines set unit_price = 0 where order_id = ${String(PEDIDO)}`),
      ).rejects.toThrow(/permission denied/i);
    } finally {
      await client.query("rollback");
    }
  });

  it("apagar o pedido apaga as linhas", async () => {
    await client.query("begin");

    try {
      await client.query("delete from public.orders where id = $1", [PEDIDO]);
      const { rows } = await client.query("select 1 from public.ml_sales_lines where order_id = $1", [PEDIDO]);

      expect(rows).toEqual([]);
    } finally {
      await client.query("rollback");
    }
  });
});

/**
 * D-497 (b): a recusa da nota de venda de marketplace tem código, e o CNPJ do
 * intermediador fica no documento -- a tela de notas os recebe no fim de cada
 * linha do `get_documents_overview`.
 */
describe("documents: o código da recusa e o intermediador (D-497)", () => {
  const RUN = String(Date.now());
  const ARQUIVO = `D497-${RUN}`;
  const criados: string[] = [];

  afterAll(async () => {
    await client.query("delete from public.documents where id = any($1)", [criados]);
  });

  async function documento(codigo: string | null, intermediario: string | null, sufixo: string): Promise<string> {
    const { rows } = await client.query<{ id: string }>(
      `insert into public.documents
         (organization_id, status, storage_path, file_name, content_hash, document_type, source_format,
          operation_type, last_error, last_error_code, intermediary_cnpj)
       values ($1, 'FAILED', 'nfe/d497.xml', $2, $3, 'NFE', 'XML', 'SAIDA', 'recusada', $4, $5)
       returning id`,
      [ORG_SB, `${ARQUIVO}-${sufixo}`, `${RUN}${sufixo}`.padEnd(64, "0").slice(0, 64), codigo, intermediario],
    );
    const id = rows[0]?.id ?? "";

    criados.push(id);

    return id;
  }

  it("a tela recebe o código e o intermediador na linha do documento", async () => {
    const id = await documento("SAIDA_VENDA_MARKETPLACE", "03007331000141", "a");
    const [linha] = await asUser<{ v: { linhas: Record<string, unknown>[] } }>(
      ADMIN_SB,
      `select public.get_documents_overview('${ORG_SB}', p_search => '${ARQUIVO}') as v`,
    );

    expect(linha?.v.linhas.find((l) => l.id === id)).toMatchObject({
      status: "FAILED",
      last_error: "recusada",
      last_error_code: "SAIDA_VENDA_MARKETPLACE",
      intermediary_cnpj: "03007331000141",
    });
  });

  it("aceita os quatro códigos e nulo; recusa código desconhecido e CNPJ que não tem 14 dígitos", async () => {
    for (const [i, codigo] of ["DEVOLUCAO_VENDA_MARKETPLACE", "VENDA_PEDE_XML", "LEITURA_NAO_GRAVADA", null].entries()) {
      await expect(documento(codigo, null, `b${String(i)}`)).resolves.toBeTruthy();
    }

    await expect(documento("OUTRO_MOTIVO", null, "c")).rejects.toThrow(/documents_last_error_code_check/);
    await expect(documento(null, "03.007.331/0001-41", "d")).rejects.toThrow(/documents_intermediary_cnpj_check/);
  });
});

/**
 * D-495 (b): a venda da Shopee no ledger -- os três tipos novos no CHECK e o
 * extrato das movimentações com a loja e o dia do pedido (para o link "Pedido
 * Shopee" da tela). A regra da baixa é testada no domínio e no worker.
 */
describe("o ledger com a venda da Shopee (D-495)", () => {
  const LOJA = "dddd4950-0000-4000-8000-00000000d495";
  const SN = "D495-LEDGER-1";
  const RUN = String(Date.now());
  let skuId = "";

  beforeAll(async () => {
    await client.query(
      `insert into public.shopee_shops (id, organization_id, environment, shop_id, shop_name, status)
       values ($1, $2, 'live', 990495001, 'Loja Ledger', 'CONNECTED') on conflict (id) do nothing`,
      [LOJA, ORG_SB],
    );
    await client.query(
      `insert into public.shopee_orders (shopee_shop_id, organization_id, order_sn, order_status, shopee_created_at, shopee_updated_at, paid_at)
       values ($1, $2, $3, 'READY_TO_SHIP', timestamptz '2026-10-20 02:30+00', timestamptz '2026-10-20 03:00+00', timestamptz '2026-10-20 02:31+00')
       on conflict do nothing`,
      [LOJA, ORG_SB, SN],
    );
    const sku = await client.query<{ id: string }>(
      `insert into public.skus (organization_id, sku, kind, purchase_cost)
       values ($1, 'RLSTEST-D495', 'PRODUTO', 20)
       on conflict on constraint skus_org_key_unique do update set sku = excluded.sku
       returning id`,
      [ORG_SB],
    );

    skuId = sku.rows[0]?.id ?? "";
  });

  afterAll(async () => {
    await client.query("delete from public.shopee_shops where id = $1", [LOJA]);
  });

  const movimento = (tipo: string, chave: string, qtd: number, origem = "SHOPEE_ORDER", id = SN) =>
    client.query(
      `insert into public.stock_movements (organization_id, sku_id, location_kind, qty_delta, movement_type, source_type, source_id, idempotency_key, occurred_at)
       values ($1, $2, 'LOCAL', $3, $4, $5, $6, $7, timestamptz '2026-10-20 02:31+00')`,
      [ORG_SB, skuId, qtd, tipo, origem, id, `${chave}:${RUN}`],
    );

  it("o CHECK aceita os três tipos da Shopee e recusa um tipo que não existe", async () => {
    await movimento("VENDA_SHOPEE", "d495-venda", -1);
    await movimento("ESTORNO_ARMAZEM_SHOPEE", "d495-armazem", 1);
    await movimento("CANCELAMENTO_SHOPEE", "d495-cancel", 1);
    await expect(movimento("VENDA_TIKTOK", "d495-x", -1)).rejects.toThrow(/stock_movements_movement_type_check/);
  });

  it("o extrato traz a loja e o dia do pedido (São Paulo) para SHOPEE_ORDER, e nulos para o resto", async () => {
    await movimento("VENDA_SHOPEE", "d495-sem-pedido", -1, "SHOPEE_ORDER", "NAO-EXISTE");

    const linhas = await asUser<{ source_type: string; source_id: string; shopee_shop_id: string | null; shopee_order_day: string | null }>(
      ADMIN_SB,
      `select source_type, source_id, shopee_shop_id::text, shopee_order_day::text
         from public.get_stock_movements('${ORG_SB}', p_limit => 200, p_search => 'RLSTEST-D495')`,
    );
    const daShopee = linhas.find((l) => l.source_id === SN);
    const semPedido = linhas.find((l) => l.source_id === "NAO-EXISTE");

    // 02:30 UTC de 20/10 é 23:30 de 19/10 em São Paulo: o dia é o de lá.
    expect(daShopee).toMatchObject({ source_type: "SHOPEE_ORDER", shopee_shop_id: LOJA, shopee_order_day: "2026-10-19" });
    expect(semPedido).toMatchObject({ shopee_shop_id: null, shopee_order_day: null });
  });
});

/*
  D-619: o estoque do anúncio da Shopee fresco. A venda baixa o estoque na
  Shopee sem mudar o update_time do item: a fila do detalhe relê o item ativo
  lido há mais de 6 horas, e a ruptura (D-611) só lê o estoque da última
  leitura boa e não roda com o catálogo atrasado (30 horas).
*/
describe("o estoque do anúncio da Shopee fresco (D-619)", () => {
  const ORG = "99999999-0000-4000-8000-00000000d619";
  const LOJA = "dddd6190-0000-4000-8000-0000000a0619";

  const sincronizar = async (dia: string) =>
    (
      await client.query<{ r: { fontes: string[]; criadas: number; encerradas: number } }>(
        "select public.sincronizar_alertas_central($1, $2::date, array['shopee_ruptura']) as r",
        [ORG, dia],
      )
    ).rows[0]?.r;

  const acoes = async () =>
    (
      await client.query<{ subject_key: string; status: string; detector: Record<string, unknown>; evidencias: { tipo: string; descricao: string }[] }>(
        `select subject_key, status, evidence -> 'detector' as detector, evidence -> 'evidencias' as evidencias
           from public.actions where organization_id = $1 and kind = 'shopee_ruptura' order by subject_key`,
        [ORG],
      )
    ).rows;

  beforeAll(async () => {
    await client.query("insert into public.organizations (id, name, slug) values ($1, 'Org D-619', 'org-d619') on conflict (id) do nothing", [ORG]);
    await client.query(
      `insert into public.shopee_shops (id, organization_id, environment, shop_id, shop_name, status, connected_at, orders_synced_until, orders_last_success_at, items_synced_until)
       values ($1, $2, 'live', 990619001, 'Loja Real', 'CONNECTED', now() - interval '60 days', now(), now(), now())
       on conflict do nothing`,
      [LOJA, ORG],
    );
    // 1: zerado, lido agora. 2: zerado, mas a última leitura falhou (o estoque
    // é o de antes). 3: com estoque, lido agora. 4: fora do ar, lido há 2 dias.
    // 5: com estoque, lido há 7 horas (e mudado antes do 3, para a ordem ser a
    // da leitura, não a da mudança).
    await client.query(
      `insert into public.shopee_items (shopee_shop_id, organization_id, item_id, item_status, shopee_updated_at, item_name, has_model, details_synced_at, details_update_time, details_error, available_stock)
       values ($1, $2, 1, 'NORMAL', now() - interval '3 days', 'Zerado', false, now(), now() - interval '3 days', null, 0),
              ($1, $2, 2, 'NORMAL', now() - interval '3 days', 'Zerado, leitura falhou', false, now(), now() - interval '3 days', 'nao_devolvido', 0),
              ($1, $2, 3, 'NORMAL', now() - interval '3 days', 'Com estoque', false, now(), now() - interval '3 days', null, 4),
              ($1, $2, 4, 'UNLIST', now() - interval '3 days', 'Fora do ar', false, now() - interval '2 days', now() - interval '3 days', null, 0),
              ($1, $2, 5, 'NORMAL', now() - interval '4 days', 'Lido há 7 horas', false, now() - interval '7 hours', now() - interval '4 days', null, 2)
       on conflict do nothing`,
      [LOJA, ORG],
    );
    await client.query(
      `insert into public.shopee_orders (shopee_shop_id, organization_id, order_sn, order_status, shopee_created_at, shopee_updated_at, paid_at)
       values ($1, $2, 'D619-O1', 'COMPLETED', '2026-10-10T15:00:00Z', now(), '2026-10-10T15:01:00Z')
       on conflict do nothing`,
      [LOJA, ORG],
    );
    await client.query(
      `insert into public.shopee_order_items (shopee_shop_id, order_sn, position, organization_id, item_id, model_id, quantity, discounted_price)
       values ($1, 'D619-O1', 0, $2, 1, null, 1, 40), ($1, 'D619-O1', 1, $2, 2, null, 1, 30), ($1, 'D619-O1', 2, $2, 3, null, 1, 20)
       on conflict do nothing`,
      [LOJA, ORG],
    );
  });

  afterAll(async () => {
    await client.query("delete from public.actions where organization_id = $1", [ORG]);
    await client.query("delete from public.shopee_shops where id = $1", [LOJA]);
  });

  it("a ruptura só com o estoque da última leitura boa, e com a hora dela", async () => {
    const r = await sincronizar("2026-10-12");
    const [acao, ...resto] = await acoes();

    expect(r?.fontes).toEqual(["shopee_ruptura"]);
    // O 2 está zerado, mas a última leitura falhou: o estoque é o de antes.
    expect(r?.criadas).toBe(1);
    expect(resto).toHaveLength(0);
    expect(acao?.subject_key).toBe(`${LOJA}:1:-`);
    expect(typeof acao?.detector.estoque_lido_em).toBe("string");
    expect(acao?.evidencias.find((e) => e.tipo === "estoque")?.descricao).toMatch(
      /^O estoque do anúncio na Shopee estava zerado na leitura de \d{2}\/\d{2}\/\d{4} \d{2}:\d{2}, e o anúncio segue ativo\.$/,
    );
  });

  it("com um item ativo sem leitura boa há 30 horas, a fonte não roda e nada se encerra", async () => {
    await client.query("update public.shopee_items set details_synced_at = now() - interval '31 hours' where shopee_shop_id = $1 and item_id = 3", [LOJA]);
    // O 1 voltou a ter estoque, mas a leitura do 3 está atrasada: nada se conclui.
    await client.query("update public.shopee_items set available_stock = 6 where shopee_shop_id = $1 and item_id = 1", [LOJA]);

    const dias = [];

    for (const dia of ["2026-10-13", "2026-10-14", "2026-10-15"]) dias.push(await sincronizar(dia));

    expect(dias.map((r) => r?.fontes)).toEqual([[], [], []]);
    expect((await acoes()).map((a) => a.status)).toEqual(["novo"]);
  });

  it("a fila relê o item ativo lido há mais de 6 horas, o mais antigo primeiro", async () => {
    const pendentes = await client.query<{ item_id: string }>("select item_id from public.shopee_items_details_pending($1, 50)", [LOJA]);

    // 3 (31 horas) antes de 5 (7 horas). Fora: 1 (agora), 2 (falhou agora:
    // o recuo de 1 dia), 4 (fora do ar).
    expect(pendentes.rows.map((r) => r.item_id)).toEqual(["3", "5"]);
  });
});

/*
  D-625 (C-77): a dispersão de preço do mesmo SKU na lista de /anuncios. A
  régua do diagnóstico do SKU: preço efetivo (promocional, senão o
  cadastrado), (maior − menor) ÷ menor, sobre os anúncios ATIVOS e PAUSADOS do
  conjunto de get_sku_listings (listings.sku_id ∪ vínculo ITEM, inclusive por
  variação), e o teto comparado com a dispersão CHEIA, com `>` estrito.
*/
describe("a dispersão de preço do mesmo SKU na lista de /anuncios (D-625, C-77)", () => {
  const ORG = "99999999-0000-4000-8000-00000000d625";
  const CONTA_A = "cccccccc-0000-4000-8000-0000000a0625";
  const CONTA_B = "cccccccc-0000-4000-8000-0000000b0625";
  const sku: Record<string, string> = {};

  interface Linha {
    item_id: string;
    preco_efetivo: number | null;
    sku_preco_min: number | null;
    sku_preco_max: number | null;
    sku_anuncios_com_preco: number | null;
    sku_dispersao_pct: number | null;
    sku_dispersao_sku_id: string | null;
    total_count: string;
  }

  const lista = async (extra = "") =>
    (
      await client.query<Linha>(
        `select item_id, preco_efetivo::float8, sku_preco_min::float8, sku_preco_max::float8, sku_anuncios_com_preco,
                sku_dispersao_pct::float8, sku_dispersao_sku_id, total_count::text
           from public.get_listings_dashboard($1, current_date - 29, current_date, p_limit => 50${extra})`,
        [ORG],
      )
    ).rows;

  const divergentes = async (teto: string | null) =>
    (
      await client.query<{ preco_divergente: string | null }>(
        "select preco_divergente::text from public.get_listings_dashboard_counts($1, p_preco_teto => $2::numeric)",
        [ORG, teto],
      )
    ).rows[0]?.preco_divergente;

  beforeAll(async () => {
    await client.query("insert into public.organizations (id, name, slug) values ($1, 'Org D-625', 'org-d625') on conflict (id) do nothing", [ORG]);
    await client.query(
      `insert into public.ml_accounts (id, organization_id, label, slug, status, seller_id, connected_at)
       values ($1, $3, 'Conta A', 'rlstest-d625a', 'CONNECTED', 9990625, now()),
              ($2, $3, 'Conta B', 'rlstest-d625b', 'CONNECTED', 9990626, now())
       on conflict (id) do nothing`,
      [CONTA_A, CONTA_B, ORG],
    );
    const criados = await client.query<{ id: string; sku: string }>(
      `insert into public.skus (organization_id, sku, kind)
       values ($1, 'D625-X', 'PRODUTO'), ($1, 'D625-Y', 'PRODUTO'), ($1, 'D625-Z', 'PRODUTO'), ($1, 'D625-K', 'KIT'), ($1, 'D625-W', 'PRODUTO')
       on conflict on constraint skus_org_key_unique do update set sku = excluded.sku returning id, sku`,
      [ORG],
    );

    for (const r of criados.rows) sku[r.sku.slice(-1)] = r.id;

    // X: 100, 85 (promoção sobre 100) e 95 (por variação, o 07); o 200 está
    // encerrado e fica fora. Y: 50 e 55,02 (pausado) -- 10,04%. Z: 90 e o 95
    // do 07. K: kit, um preço só. W: o outro anúncio está encerrado.
    await client.query(
      `insert into public.listings (organization_id, ml_account_id, item_id, title, status, price, promotional_price, currency_id, available_quantity, sku_id)
       values ($1, $2, 'MLB6250001', 'MLB6250001', 'active', 100, null, 'BRL', 1, $4),
              ($1, $3, 'MLB6250002', 'MLB6250002', 'active', 100, 85, 'BRL', 1, $4),
              ($1, $2, 'MLB6250003', 'MLB6250003', 'closed', 200, null, 'BRL', 0, $4),
              ($1, $2, 'MLB6250004', 'MLB6250004', 'active', 50, null, 'BRL', 1, $5),
              ($1, $3, 'MLB6250005', 'MLB6250005', 'paused', 55.02, null, 'BRL', 1, $5),
              ($1, $2, 'MLB6250006', 'MLB6250006', 'active', 70, null, 'BRL', 1, null),
              ($1, $3, 'MLB6250007', 'MLB6250007', 'active', 95, null, 'BRL', 1, null),
              ($1, $2, 'MLB6250008', 'MLB6250008', 'active', 90, null, 'BRL', 1, $6),
              ($1, $2, 'MLB6250009', 'MLB6250009', 'active', 500, null, 'BRL', 1, $7),
              ($1, $2, 'MLB6250010', 'MLB6250010', 'active', 40, null, 'BRL', 1, $8),
              ($1, $3, 'MLB6250011', 'MLB6250011', 'closed', 60, null, 'BRL', 0, $8)
       on conflict do nothing`,
      [ORG, CONTA_A, CONTA_B, sku.X, sku.Y, sku.Z, sku.K, sku.W],
    );
    await client.query(
      `insert into public.sku_listing_links (organization_id, ml_account_id, sku_id, ref_kind, item_id, variation_id)
       values ($1, $2, $3, 'ITEM', 'MLB6250007', '1'), ($1, $2, $4, 'ITEM', 'MLB6250007', '2')`,
      [ORG, CONTA_B, sku.X, sku.Z],
    );
  });

  afterAll(async () => {
    await client.query("delete from public.sku_listing_links where organization_id = $1", [ORG]);
    await client.query("delete from public.listings where organization_id = $1", [ORG]);
  });

  it("cada linha leva o preço ao comprador e a dispersão do SKU entre os ativos e pausados", async () => {
    const linhas = await lista();
    const por = Object.fromEntries(linhas.map((l) => [l.item_id, l]));
    const x = { sku_preco_min: 85, sku_preco_max: 100, sku_anuncios_com_preco: 3, sku_dispersao_pct: 17.6, sku_dispersao_sku_id: sku.X };

    expect(linhas).toHaveLength(11);
    expect(por.MLB6250002).toMatchObject({ preco_efetivo: 85, ...x });
    expect(por.MLB6250001).toMatchObject({ preco_efetivo: 100, ...x });
    // O encerrado não entra no conjunto, mas a linha dele mostra a dispersão do SKU.
    expect(por.MLB6250003).toMatchObject({ preco_efetivo: 200, ...x });
    // Por variação: X (17,6%) e Z (5,6%) -- a linha leva a maior, e diz qual.
    expect(por.MLB6250007).toMatchObject({ preco_efetivo: 95, ...x });
    expect(por.MLB6250008).toMatchObject({ sku_dispersao_pct: 5.6, sku_dispersao_sku_id: sku.Z, sku_anuncios_com_preco: 2 });
    // 10,04% aparece como 10,0: o arredondamento é só da exibição.
    expect(por.MLB6250004).toMatchObject({ sku_dispersao_pct: 10, sku_dispersao_sku_id: sku.Y, sku_preco_min: 50, sku_preco_max: 55.02 });
    // Sem SKU, kit de um preço só, e SKU com o outro anúncio encerrado: nulos.
    for (const item of ["MLB6250006", "MLB6250009", "MLB6250010", "MLB6250011"]) {
      expect(por[item]).toMatchObject({ sku_preco_min: null, sku_preco_max: null, sku_anuncios_com_preco: null, sku_dispersao_pct: null, sku_dispersao_sku_id: null });
    }
  });

  it("'divergente' compara a dispersão cheia com o teto, com > estrito, e a faixa conta o mesmo recorte", async () => {
    const dez = await lista(", p_preco => 'divergente', p_preco_teto => 10");
    const dezECinco = await lista(", p_preco => 'divergente', p_preco_teto => 10.05");

    expect(dez.map((l) => l.item_id).sort()).toEqual(["MLB6250001", "MLB6250002", "MLB6250003", "MLB6250004", "MLB6250005", "MLB6250007"]);
    expect(dez[0]?.total_count).toBe("6");
    expect(await divergentes("10")).toBe("6");
    // 10,04% não passa de 10,05%: só o X fica.
    expect(dezECinco.map((l) => l.item_id).sort()).toEqual(["MLB6250001", "MLB6250002", "MLB6250003", "MLB6250007"]);
    expect(await divergentes("10.05")).toBe("4");
    // O teto igual à dispersão (10,04%) não acende: `>` estrito, na lista e na faixa.
    expect((await lista(", p_preco => 'divergente', p_preco_teto => 10.04")).map((l) => l.item_id).sort()).toEqual([
      "MLB6250001", "MLB6250002", "MLB6250003", "MLB6250007",
    ]);
    expect(await divergentes("10.04")).toBe("4");
    // Sem teto não há régua: a contagem é nula, e o filtro é recusado.
    expect(await divergentes(null)).toBeNull();
    await expect(lista(", p_preco => 'divergente'")).rejects.toThrow(/p_preco_teto/);
  });

  it("a ordem pela dispersão vai do maior ao menor, com os sem dispersão no fim", async () => {
    const linhas = await lista(", p_order => 'dispersao_desc'");

    expect(linhas.map((l) => l.item_id)).toEqual([
      "MLB6250001", "MLB6250002", "MLB6250003", "MLB6250007",
      "MLB6250004", "MLB6250005",
      "MLB6250008",
      "MLB6250006", "MLB6250009", "MLB6250010", "MLB6250011",
    ]);
  });
});
